package analyzer

import "github.com/Bluezly/CIRadar/internal/model"

func catalogRealWorldRules() []catalogRuleSpec {
	return []catalogRuleSpec{
		{id: "real-go-staticcheck-sa1019", category: model.CategoryCodeFailure, provider: "Staticcheck", operation: "static-analysis", errorFamily: "deprecated-api", weight: -92, signalGroup: "static-analysis", summary: "Staticcheck rejected use of a deprecated Go API", recommendation: "Replace the deprecated API with the supported alternative named by Staticcheck, then rerun the same Staticcheck version.", pattern: `\.go:\d+:\d+: .* has been deprecated since Go [0-9.]+:.*\(SA1019\)`},
		{id: "real-go-staticcheck-diagnostic", category: model.CategoryCodeFailure, provider: "Staticcheck", operation: "static-analysis", errorFamily: "static-analysis-failure", weight: -72, signalGroup: "static-analysis", summary: "Staticcheck reported a deterministic source diagnostic", recommendation: "Fix the reported Staticcheck diagnostic or intentionally configure that check with a documented project policy.", pattern: `(?m)(?:^[^\n]*\.go:\d+:\d+:[^\n]*\((?:SA|S|ST|QF|U)\d{4}\)|^\s*\(\d+,\s*\d+\)\s+(?:SA|S|ST|QF|U)\d{4}\s+[^\n]+$)`},
		{id: "real-pnpm-outdated-lockfile", category: model.CategoryCodeFailure, provider: "pnpm", operation: "dependency-install", errorFamily: "outdated-lockfile", weight: -88, signalGroup: "dependency-lock", summary: "pnpm rejected an install because the lockfile does not match the package manifest", recommendation: "Regenerate pnpm-lock.yaml with the intended pnpm version and commit the lockfile change instead of disabling frozen-lockfile in CI.", pattern: `ERR_PNPM_OUTDATED_LOCKFILE|Cannot install with ["']?frozen-lockfile["']? because pnpm-lock\.yaml is not up to date`},
		{id: "real-corepack-signing-key", category: model.CategoryToolchainFailure, provider: "Corepack", operation: "package-manager-bootstrap", errorFamily: "signature-key-mismatch", weight: 88, signalGroup: "toolchain", summary: "Corepack could not validate the package manager signature with its bundled signing keys", recommendation: "Update Corepack or the Node.js toolchain to a version containing the current signing keys, then retry without changing application dependencies.", pattern: `corepack(?s:.*)Cannot find matching keyid|Cannot find matching keyid:.*signatures.*keys`},
		{id: "real-npm-peer-resolution", category: model.CategoryCodeFailure, provider: "npm", operation: "dependency-resolution", errorFamily: "peer-dependency-conflict", weight: -86, signalGroup: "dependency-lock", summary: "npm could not resolve the dependency tree because peer requirements conflict", recommendation: "Align the conflicting dependency and peer-dependency ranges; avoid --force or --legacy-peer-deps unless the compatibility risk is understood.", pattern: `npm (?:ERR!|error) (?:code )?ERESOLVE(?s:.*)(?:unable to resolve dependency tree|Could not resolve dependency)`},
		{id: "real-node-require-esm", category: model.CategoryCodeFailure, provider: "Node.js", operation: "module-loading", errorFamily: "commonjs-esm-mismatch", weight: -84, signalGroup: "deterministic", summary: "CommonJS code attempted to require an ES module", recommendation: "Use a compatible dependency version or migrate the call site to ESM import semantics supported by the active Node.js version.", pattern: `Error \[ERR_REQUIRE_ESM\]: require\(\) of ES Module .* not supported`},
		{id: "real-git-dubious-ownership", category: model.CategoryCodeFailure, provider: "Git", operation: "repository-access", errorFamily: "dubious-ownership", weight: -82, signalGroup: "repository-config", summary: "Git rejected the repository because its ownership does not match the executing user", recommendation: "Correct repository ownership or add the exact trusted checkout path to safe.directory; do not globally trust arbitrary paths.", pattern: `fatal: detected dubious ownership in repository at`},
		{id: "real-git-non-fast-forward", category: model.CategoryConcurrencyConflict, provider: "Git", operation: "push", errorFamily: "non-fast-forward", weight: 84, signalGroup: "concurrency", summary: "Git rejected a push because the remote branch advanced", recommendation: "Fetch the remote branch, reconcile the concurrent changes, and push the resulting history instead of overwriting it blindly.", pattern: `\[rejected\].*\(non-fast-forward\)|non-fast-forward updates were rejected|failed to push some refs(?s:.*)fetch first`},
		{id: "real-github-actions-token-permission", category: model.CategoryCodeFailure, provider: "GitHub Actions", operation: "api-authorization", errorFamily: "workflow-token-permission", weight: -90, signalGroup: "workflow-permission", summary: "GitHub rejected the workflow token for the requested API operation", recommendation: "Grant only the required workflow permission and verify whether the event source, such as Dependabot, intentionally receives a restricted token.", pattern: `(?:403:? )?Resource not accessible by integration`},
		{id: "real-github-actions-oidc-permission", category: model.CategoryCodeFailure, provider: "GitHub Actions OIDC", operation: "oidc-token", errorFamily: "id-token-permission-missing", weight: -90, signalGroup: "workflow-permission", summary: "The workflow cannot request a GitHub OIDC token", recommendation: "Add id-token: write to the job or workflow permissions and retain only the other permissions the job actually needs.", pattern: `ACTIONS_ID_TOKEN_REQUEST_URL.*(?:not set|missing|undefined|Unable to get)|Unable to get ACTIONS_ID_TOKEN_REQUEST_(?:URL|TOKEN)`},
		{id: "real-github-actions-artifact-quota", category: model.CategoryResourceExhaustion, provider: "GitHub Actions Artifacts", operation: "artifact-upload", errorFamily: "storage-quota-exceeded", weight: 92, signalGroup: "resource", summary: "GitHub Actions artifact storage quota prevented a new upload", recommendation: "Inspect Actions storage usage, artifact retention, caches, and the account or organization budget; retry only after quota capacity is available.", pattern: `(?:Failed to CreateArtifact|Create Artifact Container failed):? Artifact storage quota has been hit`},
		{id: "real-github-actions-cache-reserve", category: model.CategoryCacheFailure, provider: "GitHub Actions Cache", operation: "cache-reservation", errorFamily: "cache-reservation-failed", weight: 76, signalGroup: "cache", summary: "The workflow could not reserve a GitHub Actions cache entry", recommendation: "Retry once, then inspect cache-service health, key contention, and cache limits before changing build dependencies.", pattern: `ReserveCacheError: Unable to reserve cache with key|Unable to reserve cache with key`},
		{id: "real-gradle-class-version", category: model.CategoryToolchainFailure, provider: "Gradle/JVM", operation: "build-configuration", errorFamily: "unsupported-class-version", weight: 90, signalGroup: "toolchain", summary: "Gradle or Groovy encountered bytecode produced for a newer Java version than it supports", recommendation: "Align the JDK, Gradle wrapper, plugins, and compiled dependencies to a supported Java class-file version.", pattern: `Unsupported class file major version \d+`},
		{id: "real-maven-invalid-target-release", category: model.CategoryToolchainFailure, provider: "Maven/Javac", operation: "compile", errorFamily: "invalid-target-release", weight: 90, signalGroup: "toolchain", summary: "javac is older than the Java release targeted by the Maven build", recommendation: "Run Maven with a JDK that supports the configured source/release target or lower the target deliberately.", pattern: `Fatal error compiling: error: invalid target release:|error: release version \d+ not supported`},
		{id: "real-cargo-msrv", category: model.CategoryToolchainFailure, provider: "Cargo/Rust", operation: "dependency-resolution", errorFamily: "rust-version-too-old", weight: 90, signalGroup: "toolchain", summary: "The active Rust compiler is older than a package's minimum supported Rust version", recommendation: "Upgrade rustc or select dependency versions compatible with the project's declared Rust version.", pattern: `rustc [0-9.]+ is not supported by the following packages|cannot be built because it requires rustc [0-9.]+ or newer`},
		{id: "real-rust-linker-missing", category: model.CategoryToolchainFailure, provider: "Rust", operation: "link", errorFamily: "native-linker-missing", weight: 92, signalGroup: "toolchain", summary: "Rust could not find the native linker required for the target", recommendation: "Install the platform C/C++ build toolchain or configure the correct target linker, then rerun the build.", pattern: `error: linker [` + "`" + `'"]?(?:cc|gcc|clang|link\.exe)[` + "`" + `'"]? not found`},
		{id: "real-go-missing-sum", category: model.CategoryCodeFailure, provider: "Go modules", operation: "dependency-resolution", errorFamily: "missing-go-sum-entry", weight: -88, signalGroup: "dependency-lock", summary: "Go refused the build because go.sum is missing a required module checksum", recommendation: "Run the appropriate Go module command with the intended toolchain, review the resulting go.mod/go.sum changes, and commit them.", pattern: `missing go\.sum entry for module providing package`},
		{id: "real-go-mod-readonly", category: model.CategoryCodeFailure, provider: "Go modules", operation: "dependency-resolution", errorFamily: "module-files-out-of-date", weight: -88, signalGroup: "dependency-lock", summary: "Go detected required module-file updates while module metadata is read-only", recommendation: "Run go mod tidy with the repository's intended Go version, review the diff, and commit the required go.mod/go.sum changes.", pattern: `updates to go\.mod needed(?:;|,).*?(?:go mod tidy|disabled by -mod=readonly)|go: updates to go\.mod needed`},
		{id: "real-go-toolchain-version", category: model.CategoryToolchainFailure, provider: "Go toolchain", operation: "toolchain-selection", errorFamily: "go-version-too-old", weight: 92, signalGroup: "toolchain", summary: "The active Go toolchain is older than the version required by the module", recommendation: "Use the Go version declared by go.mod/toolchain or allow an appropriate toolchain download in CI.", pattern: `go: go\.mod requires go >= [0-9.]+ \(running go [0-9.]+(?:; GOTOOLCHAIN=local)?\)|module .* requires go >= [0-9.]+`},
		{id: "real-kubernetes-admission-webhook-timeout", category: model.CategoryNetworkFailure, provider: "Kubernetes admission webhook", operation: "admission", errorFamily: "webhook-timeout", weight: 88, signalGroup: "connectivity", summary: "The Kubernetes API server timed out while calling an admission webhook", recommendation: "Check webhook service endpoints, network policies, TLS, and webhook availability before retrying object creation.", pattern: `Failed calling webhook(?s:.*)failed calling webhook .*context deadline exceeded|failed calling webhook .* Post .* context deadline exceeded`},
		{id: "real-nuget-service-index", category: model.CategoryDependencyRegistry, provider: "NuGet", operation: "package-restore", errorFamily: "service-index-unavailable", weight: 82, signalGroup: "registry", summary: "NuGet could not load a package source service index", recommendation: "Check the NuGet source URL, TLS/certificate path, authentication, and registry availability before changing package versions.", pattern: `NU1301: Unable to load the service index for source`},
		{id: "real-terraform-lockfile-readonly", category: model.CategoryCodeFailure, provider: "Terraform", operation: "dependency-lock", errorFamily: "lockfile-read-only", weight: -82, signalGroup: "dependency-lock", summary: "Terraform could not update its dependency lock file because the working tree is read-only", recommendation: "Generate and commit .terraform.lock.hcl in a writable preparation step or deliberately configure the workflow's lockfile policy.", pattern: `Error while writing new dependency lock information to \.terraform\.lock\.hcl(?s:.*)read-only file system`},
		{id: "real-yarn-frozen-lockfile", category: model.CategoryCodeFailure, provider: "Yarn", operation: "dependency-install", errorFamily: "outdated-lockfile", weight: -88, signalGroup: "dependency-lock", summary: "Yarn rejected an install because the lockfile would need to change", recommendation: "Regenerate yarn.lock with the repository's intended Yarn version, review the dependency changes, and commit the updated lockfile.", pattern: `(?:error )?Your lockfile needs to be updated, but yarn was run with --frozen-lockfile`},
		{id: "real-poetry-lockfile-mismatch", category: model.CategoryCodeFailure, provider: "Poetry", operation: "dependency-resolution", errorFamily: "lockfile-out-of-sync", weight: -86, signalGroup: "dependency-lock", summary: "Poetry detected that poetry.lock is inconsistent with pyproject.toml", recommendation: "Regenerate the lockfile with the project's intended Poetry version and commit the reviewed lockfile change before rerunning CI.", pattern: `poetry\.lock is not consistent with pyproject\.toml`},
		{id: "real-glibc-version-not-found", category: model.CategoryToolchainFailure, provider: "glibc", operation: "native-runtime-load", errorFamily: "glibc-version-mismatch", weight: 94, signalGroup: "toolchain", summary: "A native binary requires a newer glibc symbol version than the runtime provides", recommendation: "Build against a compatible baseline, run on a newer compatible distribution, or use an artifact targeted to the runner's libc baseline.", pattern: `(?:libc\.so\.6: )?version [` + "`" + `'"]GLIBC_[0-9.]+[` + "`" + `'"] not found`},
		{id: "real-glibcxx-version-not-found", category: model.CategoryToolchainFailure, provider: "libstdc++", operation: "native-runtime-load", errorFamily: "libstdcxx-version-mismatch", weight: 94, signalGroup: "toolchain", summary: "A native binary requires a newer libstdc++ symbol version than the runtime provides", recommendation: "Align the compiler runtime with the built artifact, use a compatible base image, or rebuild against the oldest supported libstdc++ baseline.", pattern: `(?:libstdc\+\+\.so\.6: )?version [` + "`" + `'"]GLIBCXX_[0-9.]+[` + "`" + `'"] not found`},
		{id: "real-musl-loader-missing", category: model.CategoryToolchainFailure, provider: "musl libc", operation: "native-runtime-load", errorFamily: "dynamic-loader-mismatch", weight: 92, signalGroup: "toolchain", summary: "A native executable targets a musl dynamic loader that is unavailable on the runner", recommendation: "Use the binary built for the runner's libc and architecture, or run it in the matching musl-based environment instead of copying an incompatible artifact.", pattern: `(?:ld-musl-[^ :]+\.so\.1|musl[^ :]*loader)(?s:.*)(?:No such file or directory|not found)|(?:spawn|exec).*ENOENT(?s:.*)(?:musl|linux-musl)`},
		{id: "real-npm-bad-engine", category: model.CategoryToolchainFailure, provider: "npm", operation: "dependency-install", errorFamily: "node-engine-incompatible", weight: 90, signalGroup: "toolchain", summary: "npm rejected the active Node.js version for a package engine requirement", recommendation: "Use a Node.js version allowed by the package engine range or deliberately select a compatible package version instead of bypassing engine checks.", pattern: `npm (?:ERR!|error) code EBADENGINE(?s:.*)(?:Unsupported engine|Not compatible with your version of node/npm)`},
		{id: "real-yarn-bad-engine", category: model.CategoryToolchainFailure, provider: "Yarn", operation: "dependency-install", errorFamily: "node-engine-incompatible", weight: 90, signalGroup: "toolchain", summary: "Yarn rejected the active Node.js version for a package engine requirement", recommendation: "Align the CI Node.js version with the package engine requirement rather than disabling engine checks globally.", pattern: `error [^\r\n]+: The engine ["']node["'] is incompatible with this module`},
		{id: "real-npm-bad-platform", category: model.CategoryToolchainFailure, provider: "npm", operation: "dependency-install", errorFamily: "unsupported-platform", weight: 90, signalGroup: "toolchain", summary: "npm selected a package that does not support the runner operating system or CPU", recommendation: "Use a package variant compatible with the runner platform, fix optional-dependency selection, or run the job on a supported OS and architecture.", pattern: `npm (?:ERR!|error) code EBADPLATFORM(?s:.*)Unsupported platform`},
		{id: "real-npm-ci-lock-mismatch", category: model.CategoryCodeFailure, provider: "npm", operation: "dependency-install", errorFamily: "lockfile-out-of-sync", weight: -90, signalGroup: "dependency-lock", summary: "npm ci rejected package metadata because package-lock.json is out of sync", recommendation: "Run npm install with the repository's intended npm version, review package-lock.json, and commit the lockfile update before rerunning npm ci.", pattern: `npm (?:ERR!|error) code EUSAGE(?s:.*)npm ci.*(?:package-lock\.json|npm-shrinkwrap\.json).*in sync`},
		{id: "real-node-package-path-not-exported", category: model.CategoryCodeFailure, provider: "Node.js", operation: "module-loading", errorFamily: "package-subpath-not-exported", weight: -86, signalGroup: "deterministic", summary: "Node.js rejected access to a package subpath that is not exported", recommendation: "Use the package's public export path or update the caller/dependency to a version compatible with the package exports map.", pattern: `Error \[ERR_PACKAGE_PATH_NOT_EXPORTED\]: Package subpath .* is not defined by ["']exports["']`},
		{id: "real-typescript-missing-type-definition", category: model.CategoryCodeFailure, provider: "TypeScript", operation: "compile", errorFamily: "missing-type-definition", weight: -86, signalGroup: "deterministic", summary: "TypeScript could not resolve a configured type definition library", recommendation: "Install or restore the required type package and verify tsconfig types/typeRoots and monorepo dependency installation before changing compiler strictness.", pattern: `error TS2688: Cannot find type definition file for`},
		{id: "real-python-numpy-abi-mismatch", category: model.CategoryToolchainFailure, provider: "Python/NumPy", operation: "native-extension-load", errorFamily: "binary-abi-mismatch", weight: 92, signalGroup: "toolchain", summary: "A Python native extension was built against an incompatible NumPy ABI", recommendation: "Reinstall a compatible wheel set or rebuild the native extension against the NumPy version used at runtime; keep binary dependency constraints aligned.", pattern: `ValueError: numpy\.(?:dtype|ndarray) size changed, may indicate binary incompatibility`},
		{id: "real-python-shared-library-missing", category: model.CategoryToolchainFailure, provider: "Python native runtime", operation: "native-extension-load", errorFamily: "shared-library-missing", weight: 90, signalGroup: "toolchain", summary: "A Python native extension could not load a required system shared library", recommendation: "Install the required runtime library in the runner or image, or use a headless/package variant whose native dependencies match the environment.", pattern: `ImportError: (?:libGL|libEGL|libgthread|libX11|libstdc\+\+)[^:]*: cannot open shared object file: No such file or directory`},
		{id: "real-psycopg-pg-config-missing", category: model.CategoryToolchainFailure, provider: "psycopg2", operation: "native-extension-build", errorFamily: "pg-config-missing", weight: 92, signalGroup: "toolchain", summary: "psycopg2 source build could not find PostgreSQL development tooling", recommendation: "Install the PostgreSQL development package that provides pg_config or use the appropriate prebuilt package when that matches the deployment policy.", pattern: `Error: pg_config executable not found`},
		{id: "real-jvm-pkix-repository", category: model.CategoryNetworkFailure, provider: "JVM dependency repository", operation: "dependency-download", errorFamily: "certificate-trust-failure", weight: 92, signalGroup: "connectivity", summary: "The JVM could not build a trusted certificate path to a dependency repository", recommendation: "Fix the JDK trust store or corporate proxy certificate chain used by the build; do not disable TLS verification as a permanent workaround.", pattern: `PKIX path building failed(?s:.*)unable to find valid certification path to requested target`},
		{id: "real-gradle-java-version-unsupported", category: model.CategoryToolchainFailure, provider: "Gradle/JVM", operation: "build-startup", errorFamily: "gradle-java-version-incompatible", weight: 92, signalGroup: "toolchain", summary: "The Gradle version cannot understand the active Java runtime version", recommendation: "Upgrade the Gradle wrapper to a version supporting the active JDK or select a JDK supported by the project's current Gradle wrapper.", pattern: `Could not determine java version from ['"][0-9][^'"]*['"]`},
		{id: "real-java-main-class-missing", category: model.CategoryCodeFailure, provider: "Java", operation: "application-start", errorFamily: "main-class-not-found", weight: -86, signalGroup: "deterministic", summary: "The JVM could not locate the configured application entry point", recommendation: "Verify the fully qualified main class, build output, classpath/module path, and packaging step before rerunning the application.", pattern: `Error: Could not find or load main class [^\r\n]+(?s:.*)Caused by: java\.lang\.ClassNotFoundException:`},
		{id: "real-docker-exec-format", category: model.CategoryToolchainFailure, provider: "Docker", operation: "container-start", errorFamily: "binary-architecture-mismatch", weight: 94, signalGroup: "toolchain", summary: "A container attempted to execute a binary or entrypoint in an incompatible format", recommendation: "Verify image and binary OS/architecture, multi-platform build settings, emulator availability, executable format, and script line endings.", pattern: `(?:docker|containerd|runc|exec|failed to solve)(?s:.*)exec format error|exec /[^\r\n]+: exec format error`},
		{id: "real-docker-x509-registry", category: model.CategoryNetworkFailure, provider: "Docker registry", operation: "image-pull", errorFamily: "certificate-trust-failure", weight: 92, signalGroup: "connectivity", summary: "Docker could not trust the TLS certificate presented while accessing a registry", recommendation: "Install the correct registry or proxy CA certificate in the Docker daemon/build environment and verify the certificate chain instead of disabling verification.", pattern: `(?:docker|registry|pulling image|image configuration)(?s:.*)x509: certificate signed by unknown authority`},
		{id: "real-kubernetes-cni-pod-sandbox", category: model.CategoryNetworkFailure, provider: "Kubernetes CNI", operation: "pod-sandbox", errorFamily: "cni-setup-failure", weight: 92, signalGroup: "connectivity", summary: "Kubernetes could not create a pod sandbox because the CNI network setup failed", recommendation: "Inspect the node CNI plugin, CNI configuration, network daemon health, API reachability, and IP allocation before restarting application pods.", pattern: `Failed to create pod sandbox(?s:.*)(?:networkPlugin cni failed|CNI plugin.*failed|failed to set up sandbox container.*network)`},
		{id: "real-rust-openssl-missing", category: model.CategoryToolchainFailure, provider: "Rust openssl-sys", operation: "native-dependency-build", errorFamily: "openssl-development-files-missing", weight: 92, signalGroup: "toolchain", summary: "A Rust native dependency could not locate an OpenSSL development installation", recommendation: "Install the target platform OpenSSL development files or configure OPENSSL_DIR/pkg-config for the intended target; verify cross-compilation paths separately.", pattern: `Could not find directory of OpenSSL installation(?s:.*)openssl-sys|Package openssl was not found in the pkg-config search path`},
		{id: "real-github-checkout-credentials", category: model.CategoryCodeFailure, provider: "GitHub Checkout", operation: "repository-fetch", errorFamily: "git-credentials-missing", weight: -92, signalGroup: "workflow-permission", summary: "A non-interactive GitHub checkout or fetch could not obtain repository credentials", recommendation: "Verify checkout token/PAT permissions, repository or submodule access, and the remote URL; avoid embedding credentials in the repository.", pattern: `fatal: could not read Username for ['"]https://github\.com['"]: terminal prompts disabled`},
		{id: "real-github-artifact-path-missing", category: model.CategoryCodeFailure, provider: "GitHub Actions Artifacts", operation: "artifact-upload", errorFamily: "artifact-path-empty", weight: -84, signalGroup: "workflow-config", summary: "The artifact upload step did not find any files at the configured path", recommendation: "Verify the build produced the expected output and remember that action paths resolve from the action workspace rather than a shell step's working-directory defaults.", pattern: `No files were found with the provided path: [^\r\n]+\. No artifacts will be uploaded`},
	}
}
